        V("naghihintay-l35", "naghihintáy", "waiting", say="nag-hi-hin-TAY", pos="verb", group="purpose", note="Táyo ay umáwit samantaláng naghihintáy sa kanilá. Let us sing while waiting for them."),
        V("kung-hindi-l35", "kung hindî", "except, but (literally, if not)", say="kung hin-diQ", pos="phrase", group="reason", note="Shortened to kundî"),
        V("kundi-l35", "kundî", "except, but", say="kun-diQ", pos="other", group="reason", note="Shortened from kung hindî. The book also writes kundí (Síno ang tútulong sa ákin kundí ikáw?)."),
        V("dahil-sa-l35", "dáhil sa", "because of", say="DA-hil sa", pos="phrase", group="reason"),
        V("sapagkat-l35", "sapagká't", "because", say="sa-pag-KAT", pos="other", group="reason", note="Used to answer the question bakit (why)"),
        V("mangyari-l35", "mangyári", "because", say="mang-YA-ri", pos="other", group="reason", note="Used to answer the question bakit (why)"),
        V("samakatuwid-l35", "samakatuwíd", "therefore", say="sa-ma-ka-tu-WID", pos="other", group="reason", note="The book also writes samakatwíd"),
        V("pagdiriwang-l35", "pagdiríwang", "celebration", say="pag-di-RI-wang", group="reason"),
        V("kung-ano-siya-rin-l35", "kung anó … siyá rin", "as … so is …; like … like …", say="kung a-NO … si-YA rin", pos="phrase", group="more"),
        V("bunga-l35", "búnga", "fruit", say="BU-nga", group="more"),
        V("at-sa-wakas-l35", "at sa wakás", "finally, at last", say="at sa wa-KAS", pos="phrase", group="more"),
        V("ay-interj-l35", "Ay!", "expresses despair", pos="expr", group="feel", note="Ay! Ang hírap ng búhay. What a hard life!"),
        V("aba-l35", "Abá!", "expresses surprise", say="a-BA", pos="expr", group="feel"),
        V("aray-l35", "Aráy!", "expresses pain", say="a-RAY", pos="expr", group="feel"),
        V("naku-l35", "Nakú!", "expresses surprise; expresses disbelief", say="na-KU", pos="expr", group="feel", note="A shortened term for Ináy ko pô! (Oh my mother!)"),
        V("sayang-l35", "sáyang", "what a pity", say="SA-yang", pos="expr", group="feel", note="Sáyang! expresses pity"),
        V("mabuhay-l35", "Mabúhay!", "expresses welcome; expresses adoration", say="ma-BU-hay", pos="expr", group="feel", note="A welcome greeting to foreign visitors; Mabúhay si Pacquiao! Long live Pacquiao!"),
        V("inay-ko-po-l35", "Ináy ko pô!", "Oh my mother!", say="i-NAY ko poQ", pos="expr", group="feel"),
        V("susmaryosep-l35", "Susmaryosep!", "shortened form of Jesus, Maria y Jose (Jesus, Mary and Joseph)", pos="expr", group="feel"),
        V("sus-l35", "Sus!", "shortened form of Jesus", pos="expr", group="feel"),
        V("samantala-m35", "samantalá", "meanwhile, while", say="sa-man-ta-LA", pos="other", group="more2", note="Use with the present tense of verbs. Lesson 34 prints samantála."),
        V("pag-kung-m35", "pag", "if", pos="other", group="more2", note="Synonymous to kung. From: Pag umulán, hindî áko lálakad = If it rains, I shall not go. Lesson 29 gives pag as the shortened form of kapág."),
        V("umuulan-m35", "umúulan", "it is raining", say="u-MU-u-lan", pos="verb", group="more2", note="From: Ibig kong umalís péro umúulan = I like to leave but it is raining."),
        V("umulan-m35", "umulán", "it rains", say="u-mu-LAN", pos="verb", group="more2", note="From: Kung umulán, hindî áko lálakad = If it rains, I shall not go."),
        V("lalakad-m35", "lálakad", "shall go", say="LA-la-kad", pos="verb", group="more2", note="From: Kung umulán, hindî áko lálakad = If it rains, I shall not go."),
        V("umawit-m35", "umáwit", "sing", say="u-MA-wit", pos="verb", group="more2", note="From: Táyo ay umáwit samantaláng naghihintáy sa kanilá = Let us sing while waiting for them. Lesson 13 gives umáwit = sang."),
        V("maglalaba-m35", "maglalabá", "shall do the laundry", say="mag-la-la-BA", pos="verb", group="more2", note="From: Samantaláng natútúlog ang sanggól, akó'y maglalabá = While the baby sleeps, I shall do the laundry."),
        V("maingay-m35", "maingay", "noisy", pos="adj", group="more2", note="From: Huwág kang maingay nang áko'y makatúlog = Do not be noisy so I can sleep. Lesson 7 prints maíngay. Lesson 39's vocabulary list also gives maingay = noisy."),
        V("naparito-m35", "naparíto", "came", say="na-pa-RI-to", pos="verb", group="more2", note="From: Waláng naparíto kundî si Mary = Nobody came except Mary."),
        V("tutulong-m35", "tútulong", "will help", say="TU-tu-long", pos="verb", group="more2", note="From: Síno ang tútulong sa ákin kundí ikáw? = Who will help me but you?"),
        V("umiyak-m35", "umiyák", "cried", say="u-mi-YAK", pos="verb", group="more2", note="From: Umiyák siyá dáhil sa ákin = He cried because of me. Lesson 14 prints umiyàk (to cry)."),
        V("dadalo-m35", "dádalo", "shall attend", say="DA-da-lo", pos="verb", group="more2", note="From: Dáhil sa iyó, áko ay dádalo sa pagdiríwang = Because of you, I shall attend the celebration."),
        V("ayoko-m35", "ayoko", "I do not like", pos="phrase", group="more2", note="From: Hindî ka mabaít, samakatuwíd, ayoko sa iyó = You are not nice, therefore, I do not like you."),
